def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    connectors = set()
    active_sixes = set()

    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if r1 == r2 or abs(r2 - r1) != abs(c2 - c1):
                continue
            dr = 1 if r2 > r1 else -1
            dc = 1 if c2 > c1 else -1
            r, c = r1, c1
            segment = set()
            while True:
                segment.add((r, c))
                if (r, c) == (r2, c2):
                    break
                r += dr
                c += dc
            connectors.update(segment)
            active_sixes.update(segment.intersection(sixes))

    for r, c in connectors:
        if grid[r][c] != 6:
            out[r][c] = 1

    # A 6 on a 1-connector draws the perpendicular diagonal.
    for r, c in active_sixes:
        # Connector slope is +1 => perpendicular stroke has slope -1;
        # connector slope -1 => perpendicular stroke has slope +1.
        # Determine connector directions through this cell.
        directions = set()
        for i, (r1, c1) in enumerate(ones):
            for r2, c2 in ones[i + 1:]:
                if r1 == r2 or abs(r2-r1) != abs(c2-c1):
                    continue
                if min(r1, r2) <= r <= max(r1, r2) and min(c1, c2) <= c <= max(c1, c2):
                    if abs(r-r1) == abs(c-c1) and abs(r-r2) == abs(c-c2):
                        directions.add(1 if (r2-r1)*(c2-c1) > 0 else -1)
        for slope in directions:
            dr = 1
            dc = -1 if slope == 1 else 1
            rr, cc = r, c
            while 0 <= rr-dr < h and 0 <= cc-dc < w:
                rr -= dr
                cc -= dc
            while 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = 6
                rr += dr
                cc += dc

    return out
